const fileName = $json.name;
const match = fileName.match(/^(Rama|Rengga|Sahar|Syaiful)\s+Penyiapan\s+(.+)$/i);

if (!match) {
  return []; // nama belum sesuai pola (mungkin baru upload, belum di-rename) -- stop, jangan lanjut
}

const personelName = match[1];
const attachmentName = match[2].trim().replace(/\.(xlsx|xls)$/i, '').trim();

return [{ json: { fileId: $json.id, fileName, attachmentName, personelName } }];

const items = $input.all();
const lastRowData = $('Find Last Row Retur').first().json.values || [];
const nextRow = lastRowData.length + 1;
const tanggalUpload = $now.setZone('Asia/Makassar').toFormat('dd/MM/yyyy');

function toNumberIfPossible(v) {
  if (v === undefined || v === null || v === '') return v;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return (!isNaN(n) && String(v).trim() !== '') ? n : v;
}

const trimmed = [];
for (const item of items) {
  const row = item.json.row || [];
  const gin = row[0];
  if (gin === undefined || gin === null || String(gin).trim() === '') break;
  trimmed.push([row[0], row[1], row[2], row[8], tanggalUpload]);
}

const NUMERIC_COLS = [0, 1, 2, 3]; // GIN, PC, Barcode, Total pcs
const fixedRows = trimmed.map(row => {
  const r = [...row];
  for (const col of NUMERIC_COLS) r[col] = toNumberIfPossible(r[col]);
  return r;
});

// Retur upload ini sudah tertulis di run yang gagal di tengah, jangan tulis lagi
const source = $('Extract Attachment Name').first().json;
const returKey = 'retur__' + source.personelName + '__' + source.attachmentName;
const sudahTertulis = ($getWorkflowStaticData('global').processedRetur || []).some(e => e.key === returKey);

return [{ json: { values: sudahTertulis ? [] : fixedRows, nextRow } }];

const item = $json;
const key = item.personelName + '__' + item.attachmentName;
const now = Date.now();
const FIFTEEN_DAYS_MS = 15 * 24 * 60 * 60 * 1000;
const REJECTED_4_BEFORE = Date.parse('2026-11-05T13:30:00Z'); // upload 4 yang tertolak saat ActiveCutoff kosong, boleh diproses ulang

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedRetur) staticData.processedRetur = [];

// buang entri yang sudah lebih dari 15 hari
staticData.processedRetur = staticData.processedRetur.filter(
  entry => (now - entry.timestamp) < FIFTEEN_DAYS_MS
    && !(entry.key.endsWith('__4') && entry.timestamp < REJECTED_4_BEFORE)
);

// cek apakah kombinasi ini sudah pernah diproses (dalam 15 hari terakhir)
const isDuplicate = staticData.processedRetur.some(entry => entry.key === key);
if (isDuplicate) {
  return []; // sudah pernah diproses, stop di sini
}

return [item];

