const attachmentName = $('Extract Attachment Name').first().json.attachmentName;
const REQUIRED = ['Rama', 'Rengga', 'Sahar', 'Syaiful'];

const progressRows = $('Read Progress For Attachment').first().json.values || [];
const donePersonel = progressRows
  .filter(row => row[0] === attachmentName)
  .map(row => row[1]);

const allDone = REQUIRED.every(p => donePersonel.includes(p));
if (!allDone) return [];

const queueRows = $('Read Pending Queue').first().json.values || [];
const alreadyQueued = queueRows.some(row => row[0] === attachmentName);
if (alreadyQueued) return [];

return [{ json: { attachmentName } }];

const attachmentName = $('Extract Attachment Name').first().json.attachmentName;
const personelName = $('Extract Attachment Name').first().json.personelName;
const row = ($json.values && $json.values[0]) || [];
const activeAttachmentName = row[0];
const activeFileId = row[1];

if (attachmentName !== activeAttachmentName) {
  return [{ json: { isValid: false, personelName, attachmentName } }];
}

return [{ json: { isValid: true, fileId: activeFileId, fileName: activeAttachmentName } }];

const PERSONEL_MAP = { Rama: 1, Syaiful: 2, Rengga: 3, Sahar: 4 };
const personelName = $('Extract Attachment Name').first().json.personelName;
const personelCode = String(PERSONEL_MAP[personelName]);
const colE = $('Resolve STOKOPNAME Columns').first().json.colE;

const stokopnameRows = $('Read STOKOPNAME Barcodes For Stok').first().json.values || [];
if (stokopnameRows.length === 0) return [];

const alamatRows = $json.values || []; // Alamat!B2:L100000

const stokByBarcode = new Map();
for (const row of alamatRows) {
  const barcode = row[0]; // B
  if (barcode === undefined || barcode === null || String(barcode).trim() === '') continue;
  const stokAkhir = row[8]; // J
  stokByBarcode.set(String(barcode).trim(), stokAkhir);
}

// hanya sel milik personel ini, supaya upload bersamaan tidak saling menimpa
const data = [];
stokopnameRows.forEach((row, i) => {
  if (String(row[1] ?? '').trim() !== personelCode) return;
  const key = String(row[0] ?? '').trim();
  if (!stokByBarcode.has(key)) return;
  const value = stokByBarcode.get(key);
  if (value === undefined || value === null) return;
  data.push({ range: 'STOKOPNAME!' + colE + (i + 3), values: [[value]] });
});

return [{ json: { data } }];

const PERSONEL_MAP = { Rama: 1, Syaiful: 2, Rengga: 3, Sahar: 4 };
const personelCode = String(PERSONEL_MAP[$('Extract Attachment Name').first().json.personelName]);
const colF = $('Resolve STOKOPNAME Columns').first().json.colF;
const stokopnameRows = $('Read STOKOPNAME Barcodes For Stok').first().json.values || [];

// hanya baris milik personel ini, supaya upload terlambat tidak mengembalikan value lain jadi rumus
const data = [];
stokopnameRows.forEach((row, i) => {
  if (String(row[1] ?? '').trim() !== personelCode) return;
  const r = i + 3; // range mulai A3
  data.push({ range: 'STOKOPNAME!' + colF + r, values: [[`=IFERROR(VLOOKUP(A${r};PIVOT!B:C;2;0);0)`]] });
});

if (data.length === 0) return [];
return [{ json: { data } }];

const PERSONEL_MAP = { Rama: 1, Syaiful: 2, Rengga: 3, Sahar: 4 };
const personelCode = String(PERSONEL_MAP[$('Extract Attachment Name').first().json.personelName]);
const cols = $('Resolve STOKOPNAME Columns').first().json;
const stokopnameRows = $('Read STOKOPNAME Barcodes For Stok').first().json.values || [];

// hanya baris milik personel ini, sama seperti Build STOKOPNAME Formulas
const data = [];
stokopnameRows.forEach((row, i) => {
  if (String(row[1] ?? '').trim() !== personelCode) return;
  const r = i + 3; // range mulai A3
  data.push({ range: 'STOKOPNAME!' + cols.colG + r, values: [[`=${cols.colF}${r}-${cols.colE}${r}`]] });
});

if (data.length === 0) return [];
return [{ json: { data } }];

function colToIndex(col) {
  let idx = 0;
  for (const ch of col.toUpperCase()) idx = idx * 26 + (ch.charCodeAt(0) - 64);
  return idx - 1;
}
function indexToCol(idx) {
  let n = idx + 1, s = '';
  while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); }
  return s;
}

const row = ($json.values && $json.values[0]) || [];
const currentCutoffName = row[0] || '';
const lastAssignedName = row[2] || '';
const lastAssignedCol = row[3] || '';

let startCol;
let isNewCycle;
if (lastAssignedName === currentCutoffName && lastAssignedCol) {
  startCol = lastAssignedCol;
  isNewCycle = false;
} else {
  isNewCycle = true;
  startCol = lastAssignedCol ? indexToCol(colToIndex(lastAssignedCol) + 3) : 'E';
}

const colE = startCol;
const colF = indexToCol(colToIndex(startCol) + 1);
const colG = indexToCol(colToIndex(startCol) + 2);

return [{ json: { startCol, colE, colF, colG, isNewCycle, currentCutoffName } }];

function colToIndex(col) {
  let idx = 0;
  for (const ch of col.toUpperCase()) idx = idx * 26 + (ch.charCodeAt(0) - 64);
  return idx - 1;
}
function indexToCol(idx) {
  let n = idx + 1, s = '';
  while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); }
  return s;
}

const cols = $('Resolve STOKOPNAME Columns').first().json;

if (cols.colE === 'E') return []; // siklus pertama, belum ada histori buat dibandingin

// mundur sampai 3 siklus sebelumnya (tiap siklus = 3 kolom), tapi jangan sampai sebelum kolom E (siklus pertama)
const curIdx = colToIndex(cols.colE);
const earliestValidIdx = colToIndex('E');
const startIdx = Math.max(curIdx - 9, earliestValidIdx);
const colLastPrev = indexToCol(curIdx - 3); // siklus sebelumnya yang paling baru (tepat sebelum current)

return [{ json: { colStart: indexToCol(startIdx), colLastPrev, colE: cols.colE, colF: cols.colF, colG: cols.colG } }];

function colToIndex(col) {
  let idx = 0;
  for (const ch of col.toUpperCase()) idx = idx * 26 + (ch.charCodeAt(0) - 64);
  return idx - 1;
}
function indexToCol(idx) {
  let n = idx + 1, s = '';
  while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); }
  return s;
}

const PERSONEL_MAP = { Rama: 1, Syaiful: 2, Rengga: 3, Sahar: 4 };
const personelName = $('Extract Attachment Name').first().json.personelName;
const personelCode = String(PERSONEL_MAP[personelName]);

const cols = $('Check Has Previous Cycle').first().json;
const startIdx = colToIndex(cols.colStart);
const curIdx = colToIndex(cols.colE);

// daftar kolom E tiap siklus, dari yang paling lama sampai sekarang (kelipatan 3 kolom)
const cycleStartCols = [];
for (let idx = startIdx; idx <= curIdx; idx += 3) cycleStartCols.push(indexToCol(idx));

const barcodeRows = $('Read STOKOPNAME Barcodes For Stok').first().json.values || []; // A:D

const perPersonelRows = { '1': [], '2': [], '3': [], '4': [] };
const MAX_CYCLES = 4;
// Q = bandingin Selisih siklus sekarang (P) vs sebelumnya (M) di BARIS DIA SENDIRI,
// pakai ROW() biar otomatis nunjuk ke baris manapun dia nanti ditulis (append)
const Q_FORMULA = '=INDIRECT("P"&ROW())=INDIRECT("M"&ROW())';

barcodeRows.forEach((row, i) => {
  const barcode = row[0], personel = row[1], description = row[2], alamat = row[3];
  const personelKey = (personel !== undefined && personel !== null) ? String(personel).trim() : '';
  if (personelKey !== personelCode) return; // cuma barcode milik personel yang lagi upload
  if (!perPersonelRows[personelKey]) return;

  const stokRow = i + 3; // baris A3 = index 0

  // formula ref tiap siklus, urut dari paling lama -> sekarang; siklus yang belum ada historinya diisi kosong
  const padCount = MAX_CYCLES - cycleStartCols.length;
  const formulaCols = [];
  for (let p = 0; p < padCount; p++) formulaCols.push('', '', '');
  cycleStartCols.forEach(startCol => {
    const colE = startCol;
    const colF = indexToCol(colToIndex(startCol) + 1);
    const colG = indexToCol(colToIndex(startCol) + 2);
    formulaCols.push(`=STOKOPNAME!${colE}${stokRow}`, `=STOKOPNAME!${colF}${stokRow}`, `=STOKOPNAME!${colG}${stokRow}`);
  });

  perPersonelRows[personelKey].push([
    barcode, personel, description, alamat,
    ...formulaCols,
    Q_FORMULA
  ]);
});

return Object.entries(perPersonelRows)
  .filter(([, rows]) => rows.length > 0)
  .map(([personelKey, rows]) => ({ json: { personelKey, rows } }));

function colToIndex(col) {
  let idx = 0;
  for (const ch of col.toUpperCase()) idx = idx * 26 + (ch.charCodeAt(0) - 64);
  return idx - 1;
}

const cols = $('Check Has Previous Cycle').first().json;
const row = ($json.values && $json.values[0]) || [];

const prevCount = (colToIndex(cols.colLastPrev) - colToIndex(cols.colStart)) / 3 + 1;
const prevDates = [];
for (let i = 0; i < prevCount; i++) prevDates.push(row[i * 3] || '');

// nama siklus sekarang diambil dari memory (bukan baca ulang sheet), supaya nggak race
// dengan cabang paralel yang baru nulis STOKOPNAME!{colE}1 di eksekusi ini
const currentCutoffName = $('Resolve STOKOPNAME Columns').first().json.currentCutoffName;
const allDates = [...prevDates, currentCutoffName]; // oldest -> current

const MAX_CYCLES = 4;
const labels = Array(MAX_CYCLES - allDates.length).fill('').concat(allDates);

return [{ json: { labels } }];

function colToIndex(col) {
  let idx = 0;
  for (const ch of col.toUpperCase()) idx = idx * 26 + (ch.charCodeAt(0) - 64);
  return idx - 1;
}

const sheets = $json.sheets || [];
const targetTitles = ['1', '2', '3', '4'];
const selisihCols = [6, 9, 12, 15]; // G,J,M,P (0-indexed) - kolom Selisih tiap grup siklus di sheet personel

const requests = [];
for (const title of targetTitles) {
  const sheet = sheets.find(s => String(s.properties.title) === title);
  if (!sheet) continue;
  const sheetId = sheet.properties.sheetId;
  for (const col of selisihCols) {
    requests.push({
      repeatCell: {
        range: { sheetId, startColumnIndex: col, endColumnIndex: col + 1 },
        cell: { userEnteredFormat: { textFormat: { bold: true } } },
        fields: 'userEnteredFormat.textFormat.bold',
      },
    });
  }
}

// STOKOPNAME: kolom Selisih tumbuh terus tiap siklus baru (G, J, M, ...), jadi bold semua
// dari siklus pertama sampai siklus sekarang -- sekalian backfill yang lama kalau belum di-bold
const stokopnameSheet = sheets.find(s => String(s.properties.title) === 'STOKOPNAME');
const colGCurrent = $('Resolve STOKOPNAME Columns').first().json.colG;
if (stokopnameSheet && colGCurrent) {
  const sheetId = stokopnameSheet.properties.sheetId;
  const firstG = 6; // kolom G, siklus pertama
  const lastG = colToIndex(colGCurrent);
  for (let col = firstG; col <= lastG; col += 3) {
    requests.push({
      repeatCell: {
        range: { sheetId, startColumnIndex: col, endColumnIndex: col + 1 },
        cell: { userEnteredFormat: { textFormat: { bold: true } } },
        fields: 'userEnteredFormat.textFormat.bold',
      },
    });
  }
}

return [{ json: { requests } }];

// dicatat setelah tanggal terbukti cocok, supaya upload yang ditolak bisa diulang
const source = $('Extract Attachment Name').first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedRetur) staticData.processedRetur = [];
staticData.processedRetur.push({ key: source.personelName + '__' + source.attachmentName, timestamp: Date.now() });
return $input.all();

// supaya upload ulang setelah gagal di tengah tidak menulis Retur dua kali
const source = $('Extract Attachment Name').first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedRetur) staticData.processedRetur = [];
staticData.processedRetur.push({ key: 'retur__' + source.personelName + '__' + source.attachmentName, timestamp: Date.now() });
return $input.all();
